example_item.example_item_data:
% Nommer une nuit de fibrillation simulee et lire sa charge de fibrillation.
recording = ecglab.simulate('Seconds', 90, 'Fibrillation', true, 'Seed', 7);
rhythm = ecglab.rhythm(recording);
fprintf('charge FA %.2f\n', rhythm.afBurden);

% Detecter le rythme d'un enregistrement de la base FA et le comparer a ses marques.
recording = ecglab.reference('afdb/04015');
detected = ecglab.rhythm(recording);
agreement = ecglab.validate(detected, recording, 'Kind', 'episodes');
fprintf('Se duree %.2f  +P %.2f\n', agreement.durationSe, agreement.durationPpv);
